def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    cr = sum(r for r, c in points) / len(points)
    cc = sum(c for r, c in points) / len(points)

    out = [row[:] for row in grid]
    colors = set(grid[r][c] for r, c in points)

    for color in colors:
        cells = {(r, c) for r, c in points if grid[r][c] == color}
        while cells:
            start = cells.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 1):
                    for dc in (-1, 1):
                        q = (r + dr, c + dc)
                        if q in cells:
                            cells.remove(q)
                            comp.add(q)
                            stack.append(q)

            if len(comp) < 2:
                continue

            ends = []
            for r, c in comp:
                neighbors = [(r + dr, c + dc)
                             for dr in (-1, 1) for dc in (-1, 1)
                             if (r + dr, c + dc) in comp]
                if len(neighbors) == 1:
                    ends.append((r, c, neighbors[0]))

            if not ends:
                continue
            r, c, (nr, nc) = max(
                ends, key=lambda p: (p[0] - cr) ** 2 + (p[1] - cc) ** 2
            )
            dr, dc = r - nr, c - nc
            rr, ccol = r + dr, c + dc
            while 0 <= rr < h and 0 <= ccol < w:
                if out[rr][ccol] != bg:
                    break
                out[rr][ccol] = color
                rr += dr
                ccol += dc

    return out
